<?php declare(strict_types=1); require __DIR__.'/lib/bootstrap.php'; require __DIR__.'/lib/layout.php'; $user=require_login();$error=null;if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{verify_csrf();$name=trim((string)$_POST['display_name']);$email=trim((string)$_POST['email']);$password=(string)($_POST['password']??'');$confirmation=(string)($_POST['password_confirmation']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid name and email.');if($password!==''&&($password!==$confirmation||strlen($password)<12))throw new RuntimeException('New passwords must match and contain at least 12 characters.');if($password!=='')db()->prepare('UPDATE cms_users SET display_name=?,email=?,password_hash=? WHERE id=?')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$user['id']]);else db()->prepare('UPDATE cms_users SET display_name=?,email=? WHERE id=?')->execute([$name,$email,$user['id']]);$_SESSION['master_user']['display_name']=$name;$_SESSION['master_user']['email']=$email;flash('Account updated.');redirect('account.php');}catch(Throwable $e){$error=$e->getMessage();}}page_start('My account','account');?><section class="panel narrow"><h2>Profile</h2><p class="muted">Update your administrator identity and password.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" data-ajax-form data-ajax-action="account.save" data-reload="true"><?=csrf_field()?><label>Username<input value="<?=e($user['username'])?>" placeholder="Your username" disabled></label><label>Display name<input name="display_name" value="<?=e($user['display_name'])?>" placeholder="e.g. Primary Administrator" required></label><label>Email<input type="email" name="email" value="<?=e($user['email'])?>" placeholder="admin@example.com" required></label><label>New password<input type="password" name="password" placeholder="Leave blank to keep your current password" minlength="12" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="password_confirmation" placeholder="Repeat the new password" minlength="12" autocomplete="new-password"></label><button class="button primary">Save changes</button></form></section><?php page_end();
